struct Failure:std::runtime_error{int status;Failure(int code,const char* text):std::runtime_error(text),status(code){}};
void message(char* out,uint64_t capacity,const char* text){if(out&&capacity){const auto n=std::min<uint64_t>(capacity-1,std::strlen(text));std::memcpy(out,text,n);out[n]=0;}}
double finite(long double value){if(!std::isfinite(value)||std::abs(value)>std::numeric_limits<double>::max())throw Failure(2,"Unit conversion/arithmetic is outside finite binary64 range.");const double result=static_cast<double>(value);if(value!=0&&result==0)throw Failure(2,"A nonzero unit conversion/arithmetic result underflows binary64.");return result;}
struct Unit{std::array<int32_t,7> dimension{};long double scale=1;};
Unit combine(const Unit& a,const Unit& b,int power){Unit result;for(unsigned n=0;n<7;++n){const int exponent=a.dimension[n]+power*b.dimension[n];if(exponent<-32||exponent>32)throw Failure(1,"SI dimension exponents are bounded to[-32,32].");result.dimension[n]=exponent;}result.scale=power==1?a.scale*b.scale:a.scale/b.scale;if(!std::isfinite(result.scale)||result.scale<=0)throw Failure(2,"Unit scale cannot be represented.");return result;}
Unit power(Unit a,int exponent){for(auto& dimension:a.dimension){const int result=dimension*exponent;if(result<-32||result>32)throw Failure(1,"SI dimension exponents are bounded to[-32,32].");dimension=result;}a.scale=std::pow(a.scale,exponent);if(!std::isfinite(a.scale)||a.scale<=0)throw Failure(2,"Powered unit scale cannot be represented.");return a;}
const std::map<std::string,Unit>& symbols(){static const std::map<std::string,Unit> table{
 {"1",{}},{"%",{{},.01L}},{"m",{{1,0,0,0,0,0,0},1}},{"kg",{{0,1,0,0,0,0,0},1}},{"g",{{0,1,0,0,0,0,0},.001L}},
 {"s",{{0,0,1,0,0,0,0},1}},{"A",{{0,0,0,1,0,0,0},1}},{"K",{{0,0,0,0,1,0,0},1}},{"mol",{{0,0,0,0,0,1,0},1}},{"cd",{{0,0,0,0,0,0,1},1}},
 {"min",{{0,0,1,0,0,0,0},60}},{"h",{{0,0,1,0,0,0,0},3600}},{"rad",{}},{"deg",{{},3.141592653589793238462643383279502884L/180}},
 {"Hz",{{0,0,-1,0,0,0,0},1}},{"N",{{1,1,-2,0,0,0,0},1}},{"Pa",{{-1,1,-2,0,0,0,0},1}},{"J",{{2,1,-2,0,0,0,0},1}},{"W",{{2,1,-3,0,0,0,0},1}},
 {"C",{{0,0,1,1,0,0,0},1}},{"V",{{2,1,-3,-1,0,0,0},1}},{"Ohm",{{2,1,-3,-2,0,0,0},1}},{"S",{{-2,-1,3,2,0,0,0},1}},
 {"F",{{-2,-1,4,2,0,0,0},1}},{"T",{{0,1,-2,-1,0,0,0},1}},{"H",{{2,1,-2,-2,0,0,0},1}},{"Wb",{{2,1,-2,-1,0,0,0},1}}
 };return table;}
Unit symbol(const std::string& name){if(name=="degC"||name=="degF"||name=="Celsius"||name=="Fahrenheit")throw Failure(1,"Affine Celsius/Fahrenheit temperatures require explicit absolute/delta semantics and are unsupported; use linear Kelvin quantities.");if(const auto found=symbols().find(name);found!=symbols().end())return found->second;static const std::array<std::pair<std::string_view,long double>,21> prefixes{{{"da",1e1L},{"Y",1e24L},{"Z",1e21L},{"E",1e18L},{"P",1e15L},{"T",1e12L},{"G",1e9L},{"M",1e6L},{"k",1e3L},{"h",1e2L},{"d",1e-1L},{"c",1e-2L},{"m",1e-3L},{"u",1e-6L},{"n",1e-9L},{"p",1e-12L},{"f",1e-15L},{"a",1e-18L},{"z",1e-21L},{"y",1e-24L},{"",1}}};for(const auto& [prefix,scale]:prefixes)if(!prefix.empty()&&name.starts_with(prefix)){const auto base=name.substr(prefix.size());if(base=="kg"||base=="min"||base=="h"||base=="deg"||base=="1"||base=="%")continue;if(const auto found=symbols().find(base);found!=symbols().end()){auto result=found->second;result.scale*=scale;return result;}}throw Failure(1,"Unknown SI unit; use case-sensitive ASCII symbols, u for micro, and explicit * / ^ operators.");}
struct Parser{std::string_view text;std::size_t at=0;unsigned tokens=0,depth=0;bool spaces(){const auto old=at;while(at<text.size()&&(text[at]==' '||text[at]=='\t'))++at;return at!=old;}bool letter(char c){return(c>='a'&&c<='z')||(c>='A'&&c<='Z');}Unit factor(){spaces();if(++tokens>128||at>=text.size())throw Failure(1,"A bounded SI unit factor was expected.");Unit result;if(text[at]=='('){if(++depth>16)throw Failure(1,"SI unit parentheses exceed depth16.");++at;result=expression();spaces();if(at>=text.size()||text[at++]!=')')throw Failure(1,"Unclosed SI unit parentheses.");--depth;}else{const auto begin=at;if(text[at]=='1'||text[at]=='%')++at;else while(at<text.size()&&letter(text[at]))++at;if(begin==at)throw Failure(1,"Only linear ASCII SI unit expressions are supported.");result=symbol(std::string(text.substr(begin,at-begin)));}const auto end=at;spaces();if(at<text.size()&&text[at]=='^'){++at;spaces();int sign=1;if(at<text.size()&&(text[at]=='+'||text[at]=='-')){if(text[at++]=='-')sign=-1;}const auto begin=at;int exponent=0;while(at<text.size()&&text[at]>='0'&&text[at]<='9'){exponent=exponent*10+text[at++]-'0';if(exponent>32)throw Failure(1,"SI powers are bounded integer exponents[-32,32].");}if(at==begin)throw Failure(1,"SI powers require an explicit integer exponent.");result=power(result,sign*exponent);}else at=end;return result;}Unit expression(){auto result=factor();for(;;){const bool gap=spaces();if(at==text.size()||text[at]==')')break;int direction=1;if(text[at]=='*'||text[at]=='/'){if(text[at++]=='/')direction=-1;}else if(!(gap&&(letter(text[at])||text[at]=='('||text[at]=='1'||text[at]=='%')))throw Failure(1,"Expected SI product, quotient or integer power.");result=combine(result,factor(),direction);}return result;}};
std::string canonical(const std::array<int32_t,7>& dimensions){static const char* base[]{"m","kg","s","A","K","mol","cd"};std::string result;for(unsigned n=0;n<7;++n)if(dimensions[n]){if(!result.empty())result+='*';result+=base[n];if(dimensions[n]!=1)result+='^'+std::to_string(dimensions[n]);}return result.empty()?"1":result;}
penta_si_unit_v1 descriptor(const Unit& unit){penta_si_unit_v1 out{};std::copy(unit.dimension.begin(),unit.dimension.end(),out.dimensions);out.scale=finite(unit.scale);const auto text=canonical(unit.dimension);std::copy(text.begin(),text.end(),out.canonical);return out;}
Unit checked(const penta_si_unit_v1& value){Unit result;std::copy_n(value.dimensions,7,result.dimension.begin());for(const auto n:result.dimension)if(n<-32||n>32)throw Failure(1,"Invalid bounded SI dimension exponents.");if(!std::isfinite(value.scale)||value.scale<=0)throw Failure(1,"SI conversion factors must be positive finite real values.");result.scale=value.scale;return result;}
int parse(const char* text,penta_si_unit_v1* out,char* error,uint64_t capacity)noexcept{try{if(!text||!out)throw Failure(1,"SI unit text/output is missing.");std::size_t length=0;while(length<=512&&text[length])++length;if(length>512)throw Failure(1,"SI unit expressions exceed512 bytes.");Parser parser{std::string_view(text,length)};parser.spaces();if(parser.at==length)throw Failure(1,"Use explicit unit1 for dimensionless values.");const auto result=parser.expression();parser.spaces();if(parser.at!=length)throw Failure(1,"Unexpected trailing SI unit content.");*out=descriptor(result);return 0;}catch(const Failure& e){message(error,capacity,e.what());return e.status;}catch(const std::exception& e){message(error,capacity,e.what());return 2;}catch(...){message(error,capacity,"Unknown SI parser failure.");return 4;}}
uint64_t elements(uint64_t rows,uint64_t columns){if(rows>8000000||columns>100000||(columns&&rows>8000000/columns))throw Failure(7,"Quantity arrays exceed eight million bounded real values.");return rows*columns;}
bool overlap(const double* a,uint64_t na,const double* b,uint64_t nb){if(!na||!nb)return false;const auto first=reinterpret_cast<std::uintptr_t>(a),second=reinterpret_cast<std::uintptr_t>(b);if(first>UINTPTR_MAX-na*sizeof(double)||second>UINTPTR_MAX-nb*sizeof(double))throw Failure(1,"Invalid quantity buffer address range.");return first<second+nb*sizeof(double)&&second<first+na*sizeof(double);}
struct Task{const penta_units_host_v1& host;const penta_units_request_v1& r;penta_units_result_v1& out;uint64_t aCount,bCount;static int run(void* raw,uint64_t first,uint64_t last,char* error,uint64_t capacity)noexcept{auto& self=*static_cast<Task*>(raw);try{for(auto n=first;n<last;++n){if((n&255)==0&&self.host.cancelled&&self.host.cancelled(self.host.context))throw Failure(3,"Quantity arithmetic cancelled.");const long double a=self.r.a[self.aCount==1?0:n],b=self.bCount?self.r.b[self.bCount==1?0:n]:0;if(!std::isfinite(a)||!std::isfinite(b))throw Failure(2,"Quantity input values must be finite.");long double value=0;switch(self.r.operation){case PENTA_UNIT_CONVERT:value=a*self.r.a_unit.scale/self.r.b_unit.scale;break;case PENTA_UNIT_ADD:value=a+b*self.r.b_unit.scale/self.r.a_unit.scale;break;case PENTA_UNIT_SUBTRACT:value=a-b*self.r.b_unit.scale/self.r.a_unit.scale;break;case PENTA_UNIT_MULTIPLY:value=a*self.r.a_unit.scale*b*self.r.b_unit.scale;break;case PENTA_UNIT_DIVIDE:if(b==0)throw Failure(2,"Quantity division by zero.");value=(a*self.r.a_unit.scale)/(b*self.r.b_unit.scale);break;case PENTA_UNIT_POWER:if(a==0&&self.r.exponent<0)throw Failure(2,"A zero quantity cannot have a negative power.");value=std::pow(a*self.r.a_unit.scale,self.r.exponent);if(a!=0&&value==0)throw Failure(2,"A powered nonzero quantity underflows the representable range.");break;default:throw Failure(1,"Unknown quantity operation.");}self.out.values[n]=finite(value);}return 0;}catch(const Failure& e){message(error,capacity,e.what());return e.status;}catch(const std::exception& e){message(error,capacity,e.what());return 2;}catch(...){message(error,capacity,"Unknown quantity worker failure.");return 4;}}};
int execute(const penta_units_host_v1* host,const penta_units_request_v1* request,penta_units_result_v1* result,char* error,uint64_t capacity)noexcept{try{if(!host||host->struct_size<sizeof(*host)||host->abi_version!=PENTA_UNITS_ABI_V1||!request||request->struct_size<sizeof(*request)||!result||result->struct_size<sizeof(*result))throw Failure(5,"Incompatible optional SI quantity ABI.");const auto& r=*request;if(r.operation>PENTA_UNIT_POWER||r.exponent<-32||r.exponent>32)throw Failure(1,"Unknown quantity operation or bounded integer power.");const auto a=checked(r.a_unit),b=r.operation==PENTA_UNIT_POWER?Unit{}:checked(r.b_unit);const auto na=elements(r.a_rows,r.a_columns),nb=r.operation==PENTA_UNIT_CONVERT||r.operation==PENTA_UNIT_POWER?0:elements(r.b_rows,r.b_columns);if((na&&!r.a)||(nb&&!r.b))throw Failure(1,"Quantity input buffers are missing.");uint64_t rows=r.a_rows,columns=r.a_columns;const bool binary=r.operation!=PENTA_UNIT_CONVERT&&r.operation!=PENTA_UNIT_POWER;if(binary){if(na==1){rows=r.b_rows;columns=r.b_columns;}else if(nb!=1&&(r.a_rows!=r.b_rows||r.a_columns!=r.b_columns))throw Failure(1,"Quantity arithmetic requires equal array shapes or explicit scalar expansion.");}const auto count=elements(rows,columns);if(count>result->capacity||(count&&!result->values))throw Failure(7,"Quantity output capacity is insufficient.");if(overlap(result->values,count,r.a,na)||overlap(result->values,count,r.b,nb))throw Failure(1,"Quantity output must not alias its input buffers.");Unit output;
    if(r.operation<=PENTA_UNIT_SUBTRACT){if(a.dimension!=b.dimension)throw Failure(1,"Incompatible SI dimensions for conversion/addition/subtraction.");output=r.operation==PENTA_UNIT_CONVERT?b:a;}else{auto canonicalA=a;canonicalA.scale=1;output=r.operation==PENTA_UNIT_POWER?power(canonicalA,r.exponent):combine(a,b,r.operation==PENTA_UNIT_MULTIPLY?1:-1);output.scale=1;}result->unit=descriptor(output);result->rows=rows;result->columns=columns;const uint64_t work=count*8+7;if(work>r.max_work)throw Failure(7,"Quantity native work allowance exceeded.");if(host->cancelled&&host->cancelled(host->context))throw Failure(3,"Quantity arithmetic cancelled.");Task task{*host,r,*result,na,nb};const int status=host->parallel_for?host->parallel_for(host->context,count,8,Task::run,&task,error,capacity):Task::run(&task,0,count,error,capacity);if(status)return status;if(host->charge&&host->charge(host->context,work,error,capacity))return 7;result->work_units=work;return 0;
}catch(const Failure& e){message(error,capacity,e.what());return e.status;}catch(const std::exception& e){message(error,capacity,e.what());return 2;}catch(...){message(error,capacity,"Unknown native SI quantity failure.");return 4;}}
const penta_units_api_v1 api{sizeof(penta_units_api_v1),PENTA_UNITS_ABI_V1,parse,execute};
